                if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
                    ctx.status(400).json(error("INVALID_REQUEST", "Checkout must be after checkin"));
                    return;
                }

                if (guests < 1) {
                    ctx.status(400).json(error("INVALID_REQUEST", "At least one guest required"));
                    return;
