            LocalDate rCheckIn = r.getCheckIn();
            LocalDate rCheckOut = r.getCheckOut();

            if (!(checkOut.isEqual(rCheckIn) || checkOut.isBefore(rCheckIn)) &&
                !(checkIn.isEqual(rCheckOut) || checkIn.isAfter(rCheckOut))) {
                return false;
            }
        }
        return true;
    }

