        return data;
    }

    private double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }

    private Map<String, String> error(String code, String message) {
        Map<String, String> data = new LinkedHashMap<>();
        data.put("error", code);
        data.put("message", message);
        return data;
    }
