                var body = gson.fromJson(ctx.body(), JsonObject.class);

                if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
                    !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
                    !body.has("guests") || !body.has("ratePlan")) {
