                String report = reportService.generateRevenueReport(month);
                ctx.contentType("text/csv;charset=utf-8").result(report);
            } catch (DateTimeParseException e) {
                ctx.status(400).json(error("INVALID_REQUEST", "Invalid month format"));
            }
        });

